function ThemeToggle({ className }: { className?: string }) {
  const { theme, toggleTheme } = useTheme();
  const isDark = theme === 'dark';
  return (
    <button
      onClick={toggleTheme}
      aria-label={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
      className={cn(
        'w-9 h-9 rounded-lg bg-surface-hover/60 hover:bg-border-strong flex items-center justify-center text-fg-muted hover:text-fg transition-colors',
        className
      )}
    >
      {isDark ? <Sun className="w-[18px] h-[18px]" /> : <Moon className="w-[18px] h-[18px]" />}
    </button>
  );
}

// ─── TYPES ───
type View = 'landing' | 'login' | 'signup' | 'dashboard' | 'projects' | 'video-studio' | 'film-director' | 'characters' | 'timeline' | 'audio' | 'history' | 'settings';
