interface Shot { id: string; sceneId: string; projectId: string; shotNumber: string; description: string; dialogue: string; speaker?: string; characterIds: string[]; cameraAngle: CameraAngle; cameraMovement: CameraMovement; actingInstructions: string; lighting: Lighting; soundCues: string; durationSeconds: number; continuityNotes: string; status: 'planned' | 'generating' | 'generated' | 'failed'; sortOrder: number; createdAt: string; updatedAt: string; }
type JobStatus = 'queued' | 'processing' | 'completed' | 'failed';
interface GenerationJob { id: string; projectId: string; projectName: string; type: string; status: JobStatus; prompt: string; model: string; progress: number; durationSeconds: number; aspectRatio: string; createdAt: string; completedAt?: string; error?: string; resultThumbnailColor?: string; }

const STATUS_META: Record<ProjectStatus, { label: string; variant: string }> = { draft: { label: 'Draft', variant: 'default' }, 'in-progress': { label: 'In Progress', variant: 'warning' }, review: { label: 'In Review', variant: 'info' }, completed: { label: 'Completed', variant: 'success' } };
const SHOT_STATUS_META = { planned: { label: 'Planned', variant: 'default' }, generating: { label: 'Generating', variant: 'warning' }, generated: { label: 'Generated', variant: 'success' }, failed: { label: 'Failed', variant: 'error' } };

// ─── CONTEXT ───
type NewProject = Omit<Project, 'id' | 'createdAt' | 'updatedAt' | 'lastOpenedAt'>;
type NewCharacter = Omit<Character, 'id' | 'createdAt' | 'updatedAt'>;
