  isAuthed: boolean; authLoading: boolean; authConfigured: boolean; userDisplayName: string; userInitials: string; userEmail: string;
  signIn: (email: string, password: string) => Promise<string | null>;
  signUp: (email: string, password: string, fullName: string) => Promise<string | null>;
  signOut: () => Promise<void>;
  dataError: string | null;
  sidebarOpen: boolean; setSidebarOpen: (v: boolean) => void;
  projects: Project[]; characters: Character[]; scenes: Scene[]; shots: Shot[]; jobs: GenerationJob[];
  addProject: (p: NewProject) => Promise<string | null>;
  updateProject: (id: string, patch: Partial<Project>) => Promise<string | null>;
  deleteProject: (id: string) => Promise<string | null>;
  addCharacter: (c: NewCharacter) => Promise<string | null>;
  updateCharacter: (id: string, patch: Partial<Character>) => Promise<string | null>;
  deleteCharacter: (id: string) => Promise<string | null>;
  addScene: (s: Omit<Scene, 'id'>) => Promise<string | null>;
  updateScene: (id: string, patch: Partial<Scene>) => Promise<string | null>;
  deleteScene: (id: string) => Promise<string | null>;
  addShot: (s: Omit<Shot, 'id' | 'createdAt' | 'updatedAt'>) => Promise<string | null>;
  updateShot: (id: string, patch: Partial<Shot>) => Promise<string | null>;
  deleteShot: (id: string) => Promise<string | null>;
