function Modal({ open, onClose, title, children, maxWidth = 'max-w-lg' }: { open: boolean; onClose: () => void; title: string; children: ReactNode; maxWidth?: string }) { if (!open) return null; return <div className="fixed inset-0 z-50 flex items-center justify-center p-4 animate-fade-in"><div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} /><div className={cn('relative w-full bg-surface-2/80 backdrop-blur-xl border border-border/60 rounded-xl2 shadow-2xl animate-slide-up', maxWidth)}><div className="flex items-center justify-between px-5 py-4 border-b border-border/40"><h3 className="text-lg font-semibold">{title}</h3><button onClick={onClose} className="text-fg-subtle hover:text-fg p-1 rounded-lg hover:bg-surface-hover transition-colors"><X className="w-5 h-5" /></button></div><div className="p-5 max-h-[70vh] overflow-y-auto">{children}</div></div></div>; }
function EmptyState({ icon, title, description, action }: { icon: ReactNode; title: string; description: string; action?: ReactNode }) { return <div className="flex flex-col items-center justify-center py-16 text-center"><div className="w-16 h-16 rounded-xl2 bg-surface-hover/50 flex items-center justify-center text-primary/60 mb-4">{icon}</div><h3 className="text-lg font-semibold text-fg mb-1">{title}</h3><p className="text-sm text-fg-subtle max-w-sm mb-4">{description}</p>{action}</div>; }
