function Input({ label, ...props }: { label: string } & React.InputHTMLAttributes<HTMLInputElement>) { return <div><label className="text-xs font-medium text-fg-muted mb-1.5 block uppercase tracking-wider">{label}</label><input {...props} className={cn('w-full px-3.5 py-2.5 rounded-lg bg-surface-3 border border-border text-fg placeholder-fg-subtle text-sm focus:outline-none focus:border-primary/60 transition-all', props.className)} /></div>; }
function TextArea({ label, ...props }: { label: string } & React.TextareaHTMLAttributes<HTMLTextAreaElement>) { return <div><label className="text-xs font-medium text-fg-muted mb-1.5 block uppercase tracking-wider">{label}</label><textarea {...props} className={cn('w-full px-3.5 py-2.5 rounded-lg bg-surface-3 border border-border text-fg placeholder-fg-subtle text-sm focus:outline-none focus:border-primary/60 transition-all resize-none', props.className)} /></div>; }
